export enum LibraryPreference {
  MOVIEPY = 'MoviePy',
  FFMPEG = 'FFmpeg-Python',
  OPENCV = 'OpenCV',
}

export interface ScriptState {
  code: string;
  explanation: string;
  isLoading: boolean;
  error: string | null;
}

export interface HistoryItem {
  id: string;
  prompt: string;
  timestamp: number;
  library: LibraryPreference;
}

import { GoogleGenAI } from "@google/genai";
import { LibraryPreference } from "../types";

// Initialize Gemini Client
// We assume process.env.API_KEY is available as per instructions.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = "gemini-3-pro-preview"; // Using Pro for better coding logic

export const generatePythonScript = async (
  prompt: string,
  library: LibraryPreference,
  onStream: (chunkText: string) => void
): Promise<string> => {
  try {
    const systemInstruction = `
      You are an expert Python automation engineer specializing in video processing.
      Your goal is to generate robust, production-ready Python scripts to edit videos based on user requests.

      Guidelines:
      1. Use the requested library primarily: ${library}.
      2. If the request requires other standard libraries (os, sys, pathlib), include them.
      3. Structure the code cleanly with a main function or class.
      4. Add comments explaining complex steps.
      5. DO NOT wrap the code in markdown code blocks (like \`\`\`python). Return plain text code if possible, or minimally formatted.
      6. Include a comment block at the top with 'Requirements' listing necessary pip packages.
      7. Handle potential errors (e.g., file not found).

      If the user asks for something impossible with the chosen library, explain why in comments and use the best alternative.
    `;

    const chat = ai.chats.create({
      model: MODEL_NAME,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.2, // Low temperature for precise code
        maxOutputTokens: 8192, // Allow long scripts
      },
    });

    const resultStream = await chat.sendMessageStream({
      message: `Write a Python script to: ${prompt}`,
    });

    let fullText = "";
    for await (const chunk of resultStream) {
      const text = chunk.text;
      if (text) {
        fullText += text;
        onStream(text);
      }
    }

    return fullText;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const explainScript = async (code: string): Promise<string> => {
   try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // Flash is good enough for explanation
      contents: `Explain this Python video editing script simply to a user who might not be an expert:\n\n${code}`,
    });
    return response.text || "No explanation generated.";
   } catch (error) {
     return "Failed to generate explanation.";
   }
}

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  icon,
  className = '',
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500 shadow-lg shadow-blue-900/20",
    secondary: "bg-slate-700 text-slate-100 hover:bg-slate-600 focus:ring-slate-500 border border-slate-600",
    ghost: "bg-transparent text-slate-400 hover:text-white hover:bg-slate-800",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-500",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-4 py-2 text-sm",
    lg: "px-6 py-3 text-base",
  };

  return (
    <button
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {icon && <span className="mr-2">{icon}</span>}
      {children}
    </button>
  );
};

