import React, { useState } from 'react';
import { Copy, Download, Check } from 'lucide-react';
import { Button } from './Button';

interface CodeViewerProps {
  code: string;
  isLoading: boolean;
}

export const CodeViewer: React.FC<CodeViewerProps> = ({ code, isLoading }) => {
  const [copied, setCopied] = useState(false);

  // Simple function to clean markdown code blocks if they exist
  const cleanCode = (raw: string) => {
    return raw.replace(/```python/g, '').replace(/```/g, '').trim();
  };

  const displayCode = cleanCode(code);

  const handleCopy = async () => {
    await navigator.clipboard.writeText(displayCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const blob = new Blob([displayCode], { type: 'text/x-python' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'video_edit.py';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col h-full bg-[#1e1e1e] rounded-xl overflow-hidden shadow-2xl border border-slate-700">
      <div className="flex items-center justify-between px-4 py-3 bg-[#252526] border-b border-[#3e3e42]">
        <div className="flex space-x-2">
          <div className="w-3 h-3 rounded-full bg-red-500/80" />
          <div className="w-3 h-3 rounded-full bg-yellow-500/80" />
          <div className="w-3 h-3 rounded-full bg-green-500/80" />
          <span className="ml-3 text-xs text-slate-400 font-mono">video_edit.py</span>
        </div>
        <div className="flex space-x-2">
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={handleCopy} 
            disabled={!code || isLoading}
            title="Copy to clipboard"
          >
            {copied ? <Check size={16} className="text-green-400" /> : <Copy size={16} />}
          </Button>
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={handleDownload} 
            disabled={!code || isLoading}
            title="Download .py file"
          >
            <Download size={16} />
          </Button>
        </div>
      </div>

      <div className="relative flex-1 overflow-auto bg-[#1e1e1e] p-4 font-mono text-sm">
        {isLoading && !code ? (
           <div className="flex flex-col items-center justify-center h-full text-slate-500 space-y-4">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
             <p className="animate-pulse">Thinking in Python...</p>
           </div>
        ) : !code ? (
          <div className="flex flex-col items-center justify-center h-full text-slate-600">
            <p>Generate a script to see code here.</p>
          </div>
        ) : (
          <pre className="text-slate-300">
            <code>{displayCode}</code>
          </pre>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { generatePythonScript, explainScript } from './services/geminiService';
import { LibrarySelector } from './components/LibrarySelector';
import { CodeViewer } from './components/CodeViewer';
import { Button } from './components/Button';
import { LibraryPreference } from './types';
import { Wand2, PlayCircle, AlertCircle, FileVideo, Terminal } from 'lucide-react';

export default function App() {
  const [prompt, setPrompt] = useState('');
  const [library, setLibrary] = useState<LibraryPreference>(LibraryPreference.MOVIEPY);
  const [code, setCode] = useState('');
  const [explanation, setExplanation] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const bottomRef = useRef<HTMLDivElement>(null);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setIsGenerating(true);
    setError(null);
    setCode('');
    setExplanation('');

    try {
      const generatedCode = await generatePythonScript(prompt, library, (chunk) => {
        setCode(prev => prev + chunk);
      });

      // After code is generated, get a quick explanation
      // We don't block the UI for this, just trigger it
      explainScript(generatedCode).then(setExplanation);

    } catch (err: any) {
      setError(err.message || "Failed to generate script. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleQuickPrompt = (text: string) => {
    setPrompt(text);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 flex flex-col md:flex-row overflow-hidden">

      {/* Sidebar / Configuration Panel */}
      <div className="w-full md:w-[450px] flex flex-col bg-[#1e293b] border-r border-slate-700 h-screen overflow-y-auto z-10">
        <div className="p-6 border-b border-slate-700 bg-[#1e293b] sticky top-0 z-20">
          <div className="flex items-center space-x-2 mb-1">
             <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
                <FileVideo size={18} className="text-white" />
             </div>
             <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-400">
               AutoEditPy
             </h1>
          </div>
          <p className="text-xs text-slate-400">AI-Powered Python Video Automation</p>
        </div>

        <div className="p-6 flex-1 flex flex-col space-y-8">

          {/* Section 1: Library Config */}
          <section>
            <h2 className="text-sm font-semibold text-slate-300 uppercase tracking-wider mb-4 flex items-center">
              <Terminal size={14} className="mr-2 text-blue-400"/> Core Library
            </h2>
            <LibrarySelector selected={library} onSelect={setLibrary} />
          </section>

          {/* Section 2: Prompt Input */}
          <section className="flex-1 flex flex-col">
            <h2 className="text-sm font-semibold text-slate-300 uppercase tracking-wider mb-4 flex items-center">
              <Wand2 size={14} className="mr-2 text-blue-400"/> Automation Task
            </h2>

            <div className="relative flex-1 min-h-[150px]">
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Describe what you want to do with your video..."
                className="w-full h-full bg-slate-800 border-slate-600 rounded-xl p-4 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none placeholder-slate-500 shadow-inner"
              />
            </div>

            {/* Quick Prompts */}
            <div className="mt-4 flex flex-wrap gap-2">
              <button 
                onClick={() => handleQuickPrompt("Create a timelapse from a folder of images, 24fps.")}
                className="text-xs bg-slate-700 hover:bg-slate-600 text-slate-300 px-3 py-1.5 rounded-full transition"
              >
                Timelapse
              </button>
              <button 
                onClick={() => handleQuickPrompt("Concatenate all .mp4 files in the current directory.")}
                className="text-xs bg-slate-700 hover:bg-slate-600 text-slate-300 px-3 py-1.5 rounded-full transition"
              >
                Merge Videos
              </button>
              <button 
                onClick={() => handleQuickPrompt("Add a watermark image to the bottom right corner of input.mp4.")}
                className="text-xs bg-slate-700 hover:bg-slate-600 text-slate-300 px-3 py-1.5 rounded-full transition"
              >
                Watermark
              </button>
            </div>
          </section>

          {/* Generate Action */}
          <div className="pt-4">
             {error && (
               <div className="mb-4 p-3 bg-red-500/10 border border-red-500/50 rounded-lg flex items-start text-sm text-red-200">
                 <AlertCircle size={16} className="mt-0.5 mr-2 flex-shrink-0" />
                 {error}
               </div>
             )}

             <Button 
               onClick={handleGenerate} 
               disabled={isGenerating || !prompt}
               className="w-full h-12 text-lg shadow-xl shadow-blue-500/10"
             >
               {isGenerating ? 'Generating Script...' : 'Generate Python Script'}
             </Button>
          </div>
        </div>
      </div>

      {/* Main Content / Output Area */}
      <div className="flex-1 p-4 md:p-6 lg:p-8 overflow-hidden flex flex-col h-screen relative bg-[#0f172a]">
        {/* Background Decorative Elements */}
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-500/5 rounded-full blur-3xl pointer-events-none -translate-y-1/2 translate-x-1/2" />

        <div className="flex-1 flex flex-col h-full z-10 space-y-6">

          {/* Code Viewer Panel */}
          <div className="flex-1 min-h-0">
            <CodeViewer code={code} isLoading={isGenerating} />
          </div>

          {/* Explanation Panel (if available) */}
          {(explanation && !isGenerating) && (
            <div className="h-1/3 bg-slate-800/50 backdrop-blur-sm border border-slate-700 rounded-xl p-5 overflow-y-auto shadow-lg animate-in fade-in slide-in-from-bottom-4 duration-500">
