import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  icon,
  className = '',
  ...props 
}) => {
  // Fluent UI / Material 3 Style Base
  const baseStyles = "inline-flex items-center justify-center rounded-[6px] font-medium transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-offset-[#111] disabled:opacity-40 disabled:cursor-not-allowed";

  const variants = {
    // Solid fill, subtle gradient hint
    primary: "bg-[#0078d4] hover:bg-[#106ebe] text-white focus:ring-[#0078d4] shadow-md hover:shadow-lg active:scale-[0.98]",
    // Outlined / Card style
    secondary: "bg-[#2d2d2d] text-gray-100 border border-[#444] hover:bg-[#383838] focus:ring-[#555]",
    // Minimalist
    ghost: "bg-transparent text-gray-300 hover:bg-[#333] hover:text-white active:bg-[#444]",
    danger: "bg-[#c53030] text-white hover:bg-[#9b2c2c] focus:ring-red-500",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-5 py-2.5 text-sm", // Slightly taller for touch targets
    lg: "px-7 py-3 text-base",
  };

  return (
    <button
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`}
      {...props}
    >
      {icon && <span className="mr-2">{icon}</span>}
      {children}
    </button>
  );
};

