        finalPrompt = `I have the following local video files in the same directory as the script: [${filenames}]. ${prompt}`;
      } else {
        finalPrompt = `Source is from URL/Internet. ${prompt}`;
      }

      const generatedCode = await generatePythonScript(finalPrompt, library, (chunk) => {
        setCode(prev => prev + chunk);
      });
      explainScript(generatedCode).then(setExplanation);
    } catch (err: any) {
      setError(err.message || "Lỗi tạo script. Vui lòng thử lại.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleQuickPrompt = (text: string) => {
    setPrompt(text);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFiles = Array.from(e.target.files);
      // Avoid duplicates based on name
      setLocalFiles(prev => {
        const uniqueNewFiles = newFiles.filter(nf => !prev.some(pf => pf.name === nf.name));
        return [...prev, ...uniqueNewFiles];
      });
    }
    // Reset value so same file can be selected again if needed (after removal)
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const droppedFiles = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('video/'));
      if (droppedFiles.length === 0) {
         setError("Vui lòng chỉ thả file video.");
         setTimeout(() => setError(null), 3000);
         return;
      }
      setLocalFiles(prev => {
        const uniqueNewFiles = droppedFiles.filter(nf => !prev.some(pf => pf.name === nf.name));
        return [...prev, ...uniqueNewFiles];
      });
    }
  };

  const removeFile = (index: number) => {
    setLocalFiles(prev => prev.filter((_, i) => i !== index));
  };

  // Modern "Chip" component for quick prompts
  const QuickChip = ({ label, onClick }: { label: string, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="text-xs font-medium bg-[#333] hover:bg-[#444] text-gray-200 px-3 py-1.5 rounded-full border border-[#444] transition-colors flex items-center space-x-1"
    >
      <Sparkles size={10} className="text-[#0078d4]" />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-[#111] text-gray-100 flex flex-col md:flex-row overflow-hidden font-sans selection:bg-[#0078d4] selection:text-white">

      {/* Sidebar - Acrylic Style */}
      <div className="w-full md:w-[420px] flex flex-col bg-[#1c1c1c]/95 backdrop-blur-md border-r border-[#333] h-screen overflow-y-auto z-20 shadow-2xl">
        <div className="p-6 border-b border-[#333] sticky top-0 bg-[#1c1c1c]/95 backdrop-blur-xl z-30">
          <div className="flex items-center space-x-3 mb-1">
             <div className="w-9 h-9 bg-gradient-to-br from-[#0078d4] to-[#005a9e] rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
                <FileVideo size={20} className="text-white" />
             </div>
             <div>
                <h1 className="text-lg font-bold text-white tracking-tight">
                  AutoEditPy
                </h1>
                <div className="flex items-center space-x-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
                  <p className="text-[11px] text-gray-400 font-medium">v1.0 • Pro</p>
                </div>
             </div>
          </div>
        </div>

        <div className="p-6 flex-1 flex flex-col space-y-7">

          {/* Section: Library */}
          <section>
            <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center pl-1">
