               </div>
             )}

             <Button 
               onClick={handleGenerate} 
               disabled={isGenerating || !prompt || (inputMode === 'local' && localFiles.length === 0)}
               className="w-full h-11 text-base font-semibold shadow-[0_4px_14px_0_rgba(0,118,255,0.39)] hover:shadow-[0_6px_20px_rgba(0,118,255,0.23)] transition-shadow"
             >
               {isGenerating ? (
                 <span className="flex items-center">
                   <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></span>
                   Đang xử lý...
                 </span>
               ) : (
                 <span className="flex items-center">
                   <Wand2 size={18} className="mr-2" /> Tạo Script
                 </span>
               )}
             </Button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 lg:p-10 flex flex-col h-screen relative overflow-hidden bg-[#111]">

        {/* Subtle Background Glows */}
        <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-[#0078d4]/10 rounded-full blur-[120px] pointer-events-none" />
        <div className="absolute bottom-[-20%] left-[-10%] w-[500px] h-[500px] bg-purple-900/10 rounded-full blur-[100px] pointer-events-none" />

        <div className="flex-1 flex flex-col h-full z-10 gap-6 max-w-5xl mx-auto w-full">

          {/* Code Viewer */}
          <div className="flex-1 min-h-0 shadow-2xl rounded-lg">
            <CodeViewer code={code} isLoading={isGenerating} />
          </div>

          {/* Explanation Card */}
          {(explanation && !isGenerating) && (
            <div className="bg-[#1e1e1e] border border-[#333] rounded-lg p-5 shadow-xl animate-in fade-in slide-in-from-bottom-4 duration-500 max-h-[35%] overflow-y-auto custom-scrollbar">
               <div className="flex items-center mb-3">
                 <div className="p-1.5 bg-green-500/10 rounded-md mr-3">
                   <PlayCircle size={18} className="text-green-500" />
                 </div>
                 <h3 className="text-gray-200 font-semibold text-sm uppercase tracking-wide">
                   Hướng dẫn thực thi
                 </h3>
               </div>
               <div className="prose prose-invert prose-sm max-w-none text-gray-400 leading-relaxed whitespace-pre-line">
                 {explanation}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { GoogleGenAI } from "@google/genai";
import { LibraryPreference } from "../types";

// Initialize Gemini Client
// We assume process.env.API_KEY is available as per instructions.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = "gemini-3-pro-preview"; // Using Pro for better coding logic

export const generatePythonScript = async (
  prompt: string,
  library: LibraryPreference,
  onStream: (chunkText: string) => void
): Promise<string> => {
  try {
    const systemInstruction = `
      You are an expert Python automation engineer specializing in video processing and media acquisition.
      Your goal is to generate robust, production-ready Python scripts to download and edit videos based on user requests.

      Primary Libraries & Capabilities:
      - yt-dlp: For downloading videos from YouTube, TikTok, Facebook, Twitter, and other social platforms.
      - MoviePy / FFmpeg / OpenCV: For editing, processing, and analyzing video content.

      Guidelines:
      1. Library Selection:
         - If the user asks to DOWNLOAD videos (from a URL or general request), ALWAYS use the 'yt-dlp' library for that part of the task.
         - If the user asks to EDIT videos, use the user's preferred library: ${library}.
         - If the user asks to DOWNLOAD AND EDIT, combine them: use 'yt-dlp' to download the file to a temporary or specific path, then use ${library} to process that downloaded file.

      2. **CRITICAL - MOVIEPY IMPORTS (Fix for 'No module named moviepy.editor')**:
         - **DO NOT USE**: \`from moviepy.editor import *\` or \`import moviepy.editor as mp\`. This module is deprecated/removed in newer versions.
         - **USE DIRECT IMPORTS**: Import specific classes directly from the main package.
           Example: \`from moviepy import VideoFileClip, TextClip, CompositeVideoClip, concatenate_videoclips, vfx, AudioFileClip\`
         - For effects in MoviePy v2+: Use the \`vfx\` module import or method chaining correctly.

      3. Script Structure:
         - Clean structure (imports -> functions -> main execution).
         - If downloading, include error handling (try/except) for network issues or invalid URLs.
         - Use descriptive variable names (e.g., 'input_video_path', 'output_final.mp4').

      4. Language & Comments:
         - **IMPORTANT**: Write all comments (#) in VIETNAMESE (Tiếng Việt).
         - The variable names and logic must remain in English (standard Python practice), but the explanation within the code must be Vietnamese.

      5. Output Format:
         - DO NOT wrap code in markdown (\`\`\`python). Return plain text code.
         - Add a comment block at the top named 'Yêu cầu cài đặt' listing pip packages.
           - Example for MoviePy: \`# pip install moviepy yt-dlp\`

      6. Special Video Effects Logic (Apply when requested):
         - **Trimming / Cutting**:
           - MoviePy: Use \`clip.subclipped(start_time, end_time)\`. ensure start/end are in seconds or (min, sec) format.
           - FFmpeg: Use \`ffmpeg.input(..., ss=start_time).output(..., to=end_time)\` for fast seeking.
         - **Speed Change**: 
           - MoviePy: Use \`clip.with_speed_scaled(factor)\` (v2) or \`clip.fx(vfx.speedx, factor)\`.
           - FFmpeg: Use \`setpts\` filter for video and \`atempo\` for audio.
         - **Subtitles / Text Overlay**:
           - **MoviePy (Text)**: Use \`TextClip(text="...", font_size=..., color='white', font='Arial')\`.
             Set duration: \`.with_duration(...)\`.
             Set position: \`.with_position(('center', 'bottom'))\`.
             **Crucial**: Combine using \`CompositeVideoClip([base_video, text_clip])\`.
           - **MoviePy (File)**: If user provides a .srt/.vtt file, mention that \`SubtitlesClip\` requires ImageMagick, or suggest using FFmpeg for hard burning.
           - **FFmpeg**: 
             - Text: Use \`drawtext\` filter.
             - File: Use \`subtitles='filename.srt'\` filter (best for hard subs).
         - **Zoom (Magnification)**:
           - **Concept**: To zoom, you must crop a smaller area and resize it back to the original dimensions.
           - MoviePy: 
             \`new_w = clip.w / zoom_factor\`
             \`new_h = clip.h / zoom_factor\`
             \`clip.cropped(x_center=clip.w/2, y_center=clip.h/2, width=new_w, height=new_h).resized(width=clip.w)\`
             (Adjust x_center/y_center if the user requests zooming into a specific corner).
           - FFmpeg: Use \`scale\` and \`crop\` filters.

      7. Concatenation / Merging Logic (Apply when requested):
         - **MoviePy**: Use \`concatenate_videoclips([clip1, clip2, ...])\`. 
           - **Crucial**: If videos might have different sizes, use \`method='compose'\` to prevent errors.
         - **FFmpeg**: 
           - Preferred: Use the 'concat demuxer' method (create a temporary 'mylist.txt' file) if codecs are same.
           - Alternative: Use \`concat\` filter complex if re-encoding is needed or formats differ.

      8. Impossible Tasks:
         - If the requested library cannot perform a specific task, switch to the best alternative and explain why in the comments (in Vietnamese).
    `;

    const chat = ai.chats.create({
      model: MODEL_NAME,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.2, // Low temperature for precise code
        maxOutputTokens: 8192, // Allow long scripts
      },
    });

    const resultStream = await chat.sendMessageStream({
      message: `Write a Python script to: ${prompt}`,
    });

    let fullText = "";
    for await (const chunk of resultStream) {
      const text = chunk.text;
      if (text) {
        fullText += text;
        onStream(text);
      }
    }

    return fullText;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const explainScript = async (code: string): Promise<string> => {
   try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: `Giải thích đoạn mã Python tự động hóa video này một cách đơn giản cho người dùng bằng Tiếng Việt. Nếu mã chứa các hiệu ứng hoặc nối video, hãy giải thích ngắn gọn cách chúng hoạt động. Giữ ngắn gọn:\n\n${code}`,
    });
    return response.text || "Không thể tạo hướng dẫn.";
   } catch (error) {
     return "Không thể tạo hướng dẫn.";
   }
}

import React, { useState, useRef } from 'react';
import { generatePythonScript, explainScript } from './services/geminiService';
import { LibrarySelector } from './components/LibrarySelector';
import { CodeViewer } from './components/CodeViewer';
import { Button } from './components/Button';
import { LibraryPreference } from './types';
import { Wand2, PlayCircle, AlertCircle, FileVideo, Terminal, Sparkles, Upload, Link as LinkIcon, FolderOpen, X, Plus, ZoomIn, SlidersHorizontal, Scissors, Type, FileText } from 'lucide-react';

export default function App() {
  const [prompt, setPrompt] = useState('');
  const [library, setLibrary] = useState<LibraryPreference>(LibraryPreference.MOVIEPY);
  const [code, setCode] = useState('');
  const [explanation, setExplanation] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // New states for input mode
  const [inputMode, setInputMode] = useState<'url' | 'local'>('url');
  // Changed to array to support multiple files
  const [localFiles, setLocalFiles] = useState<File[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Active Tool State (Only one tool open at a time)
  const [activeTool, setActiveTool] = useState<'zoom' | 'trim' | 'subtitle' | null>(null);

  // Zoom Tool State
  const [zoomLevel, setZoomLevel] = useState(1.5);
  const [zoomPosition, setZoomPosition] = useState('center');

  // Trim Tool State
  const [trimStart, setTrimStart] = useState('');
  const [trimEnd, setTrimEnd] = useState('');

  // Subtitle Tool State
  const [subMode, setSubMode] = useState<'text' | 'file'>('text');
  const [subText, setSubText] = useState('');
  const [subFile, setSubFile] = useState<File | null>(null);
  const [subTime, setSubTime] = useState('');
  const [subDuration, setSubDuration] = useState('');
  const subFileInputRef = useRef<HTMLInputElement>(null);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setIsGenerating(true);
    setError(null);
    setCode('');
    setExplanation('');

    try {
      // Construct the full prompt based on mode
      let finalPrompt = prompt;

      if (inputMode === 'local') {
        const filenames = localFiles.map(f => `"${f.name}"`).join(", ");
        finalPrompt = `I have the following local video files in the same directory as the script: [${filenames}]. ${prompt}`;
      } else {
        finalPrompt = `Source is from URL/Internet. ${prompt}`;
      }

      const generatedCode = await generatePythonScript(finalPrompt, library, (chunk) => {
        setCode(prev => prev + chunk);
      });
      explainScript(generatedCode).then(setExplanation);
    } catch (err: any) {
      setError(err.message || "Lỗi tạo script. Vui lòng thử lại.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleQuickPrompt = (text: string) => {
    setPrompt(text);
  };

  const toggleTool = (tool: 'zoom' | 'trim' | 'subtitle') => {
    setActiveTool(activeTool === tool ? null : tool);
  };

  const handleAddZoom = () => {
    const positionText = zoomPosition === 'center' ? 'tâm (center)' : 
                         zoomPosition === 'top-left' ? 'góc trên bên trái (top-left)' :
                         zoomPosition === 'top-right' ? 'góc trên bên phải (top-right)' :
                         zoomPosition === 'bottom-left' ? 'góc dưới bên trái (bottom-left)' :
                         'góc dưới bên phải (bottom-right)';

    const zoomText = ` Zoom video phóng đại ${zoomLevel}x tập trung vào vị trí ${positionText}.`;
    setPrompt(prev => prev + zoomText);
    setActiveTool(null);
  };

  const handleAddTrim = () => {
    if (!trimStart && !trimEnd) return;
    let trimText = " Cắt video";
    if (trimStart) trimText += ` bắt đầu từ ${trimStart}`;
    if (trimEnd) trimText += ` và kết thúc tại ${trimEnd}`;
    trimText += ".";

    setPrompt(prev => prev + trimText);
    setActiveTool(null);
    setTrimStart('');
    setTrimEnd('');
  };

  const handleAddSubtitle = () => {
    let subPrompt = "";
    if (subMode === 'text') {
      if (!subText) return;
      subPrompt = ` Chèn văn bản "${subText}" vào video`;
      if (subTime) subPrompt += ` bắt đầu từ giây thứ ${subTime}`;
      if (subDuration) subPrompt += ` kéo dài trong ${subDuration} giây`;
      subPrompt += ".";
    } else {
      if (!subFile) return;
      subPrompt = ` Chèn phụ đề cứng (hardcode subtitles) từ file "${subFile.name}" vào video.`;
    }

    setPrompt(prev => prev + subPrompt);
    setActiveTool(null);
    setSubText('');
    setSubTime('');
    setSubDuration('');
    setSubFile(null);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFiles = Array.from(e.target.files);
      setLocalFiles(prev => {
        const uniqueNewFiles = newFiles.filter(nf => !prev.some(pf => pf.name === nf.name));
        return [...prev, ...uniqueNewFiles];
      });
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setSubFile(e.target.files[0]);
    }
    if (subFileInputRef.current) subFileInputRef.current.value = '';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const droppedFiles = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('video/'));
      if (droppedFiles.length === 0) {
         setError("Vui lòng chỉ thả file video.");
         setTimeout(() => setError(null), 3000);
         return;
      }
      setLocalFiles(prev => {
        const uniqueNewFiles = droppedFiles.filter(nf => !prev.some(pf => pf.name === nf.name));
        return [...prev, ...uniqueNewFiles];
      });
    }
  };

  const removeFile = (index: number) => {
    setLocalFiles(prev => prev.filter((_, i) => i !== index));
  };

  // Modern "Chip" component for quick prompts
  const QuickChip = ({ label, onClick }: { label: string, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="text-xs font-medium bg-[#333] hover:bg-[#444] text-gray-200 px-3 py-1.5 rounded-full border border-[#444] transition-colors flex items-center space-x-1"
    >
      <Sparkles size={10} className="text-[#0078d4]" />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-[#111] text-gray-100 flex flex-col md:flex-row overflow-hidden font-sans selection:bg-[#0078d4] selection:text-white">

      {/* Sidebar - Acrylic Style */}
      <div className="w-full md:w-[420px] flex flex-col bg-[#1c1c1c]/95 backdrop-blur-md border-r border-[#333] h-screen overflow-y-auto z-20 shadow-2xl">
        <div className="p-6 border-b border-[#333] sticky top-0 bg-[#1c1c1c]/95 backdrop-blur-xl z-30">
          <div className="flex items-center space-x-3 mb-1">
             <div className="w-9 h-9 bg-gradient-to-br from-[#0078d4] to-[#005a9e] rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
                <FileVideo size={20} className="text-white" />
             </div>
             <div>
                <h1 className="text-lg font-bold text-white tracking-tight">
                  AutoEditPy
                </h1>
                <div className="flex items-center space-x-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
                  <p className="text-[11px] text-gray-400 font-medium">v1.1 • Pro</p>
                </div>
             </div>
          </div>
        </div>

        <div className="p-6 flex-1 flex flex-col space-y-7">

          {/* Section: Library */}
          <section>
            <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center pl-1">
              Thư viện xử lý
            </h2>
            <LibrarySelector selected={library} onSelect={setLibrary} />
          </section>

          {/* Section: Input Source Mode */}
          <section>
             <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center pl-1">
              Nguồn Video
            </h2>
            <div className="bg-[#252525] p-1 rounded-lg flex border border-[#333] mb-4">
              <button 
                onClick={() => setInputMode('url')}
                className={`flex-1 flex items-center justify-center py-2 text-sm font-medium rounded-md transition-all ${inputMode === 'url' ? 'bg-[#333] text-white shadow-sm' : 'text-gray-400 hover:text-gray-200'}`}
              >
                <LinkIcon size={14} className="mr-2" /> URL Online
              </button>
              <button 
                onClick={() => setInputMode('local')}
                className={`flex-1 flex items-center justify-center py-2 text-sm font-medium rounded-md transition-all ${inputMode === 'local' ? 'bg-[#333] text-white shadow-sm' : 'text-gray-400 hover:text-gray-200'}`}
              >
                <Upload size={14} className="mr-2" /> File Cục bộ
              </button>
            </div>

            {/* Local File Uploader Area */}
            {inputMode === 'local' && (
              <div className="space-y-3">
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  onDragOver={handleDragOver}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDrop}
                  className={`
                    group relative border-2 border-dashed rounded-xl p-6 cursor-pointer transition-all flex flex-col items-center justify-center text-center
                    ${isDragging ? 'border-[#0078d4] bg-[#0078d4]/10' : 'border-[#444] hover:border-[#0078d4] bg-[#252525]/50 hover:bg-[#252525]'}
                  `}
                >
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    onChange={handleFileChange} 
                    accept="video/*"
                    multiple // Allow multiple files
                  />

                  <div className={`w-12 h-12 rounded-full flex items-center justify-center mb-3 transition-colors ${isDragging ? 'bg-[#0078d4] text-white' : 'bg-[#333] group-hover:bg-[#444] text-gray-400 group-hover:text-[#0078d4]'}`}>
                    {isDragging ? <Plus size={24} /> : <FolderOpen size={24} />}
                  </div>
                  <p className="text-sm font-medium text-gray-300">Nhấn chọn hoặc kéo thả video</p>
                  <p className="text-xs text-gray-500 mt-1">Hỗ trợ chọn nhiều file để nối/ghép</p>
                </div>

                {/* File List */}
                {localFiles.length > 0 && (
                  <div className="max-h-[150px] overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                    {localFiles.map((file, index) => (
                      <div key={`${file.name}-${index}`} className="flex items-center space-x-3 w-full bg-[#2a2a2a] p-2 rounded-lg border border-[#333] group hover:border-[#444] transition-colors">
                        <div className="w-8 h-8 bg-[#0078d4]/20 rounded-md flex items-center justify-center flex-shrink-0 text-[#0078d4]">
                          <FileVideo size={16} />
                        </div>
                        <div className="flex-1 min-w-0 text-left">
                          <p className="text-sm font-medium text-gray-200 truncate">{file.name}</p>
                          <p className="text-[10px] text-gray-500">{(file.size / (1024 * 1024)).toFixed(2)} MB</p>
                        </div>
                        <button 
                          onClick={(e) => { e.stopPropagation(); removeFile(index); }} 
                          className="p-1.5 hover:bg-red-900/30 text-gray-500 hover:text-red-400 rounded-md transition-colors"
                          title="Xóa file"
                        >
                          <X size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </section>

          {/* Section: Prompt */}
          <section className="flex-1 flex flex-col">
            <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center pl-1">
              Yêu cầu xử lý
            </h2>

            <div className="relative group">
              <div className="absolute -inset-0.5 bg-gradient-to-r from-[#0078d4] to-[#00bcf2] rounded-xl opacity-20 group-hover:opacity-40 transition duration-500 blur"></div>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder={inputMode === 'local' 
                  ? "Ví dụ: Nối tất cả video trên lại thành 1 file, sau đó thêm nhạc nền..." 
                  : "Ví dụ: Tải video từ YouTube URL, cắt lấy đoạn 00:30 đến 01:00..."
                }
                className="relative w-full min-h-[120px] bg-[#252525] border border-[#333] text-gray-100 rounded-lg p-4 text-sm focus:ring-2 focus:ring-[#0078d4] focus:border-transparent outline-none resize-none placeholder-gray-500 transition-all shadow-inner"
              />
            </div>

             {/* Tools & Effects Bar */}
             <div className="mt-4 flex flex-col space-y-3">
               <div className="flex items-center justify-between">
                 <div className="flex flex-wrap gap-2">
                    <QuickChip label="Nối video" onClick={() => handleQuickPrompt("Nối các video thành một file duy nhất.")} />
                    <QuickChip label="Tăng tốc 2x" onClick={() => handleQuickPrompt("Tăng tốc video lên gấp đôi (2x.")} />
                 </div>

                 <div className="flex space-x-2">
                   <button 
                      onClick={() => toggleTool('trim')}
                      className={`flex items-center text-xs font-medium px-3 py-1.5 rounded-md border transition-all ${activeTool === 'trim' ? 'bg-[#0078d4] text-white border-[#0078d4]' : 'bg-[#252525] text-gray-400 border-[#333] hover:text-white'}`}
                      title="Cắt Video"
                   >
                      <Scissors size={12} className="mr-1.5" />
                      Cắt
                   </button>
                   <button 
                      onClick={() => toggleTool('zoom')}
                      className={`flex items-center text-xs font-medium px-3 py-1.5 rounded-md border transition-all ${activeTool === 'zoom' ? 'bg-[#0078d4] text-white border-[#0078d4]' : 'bg-[#252525] text-gray-400 border-[#333] hover:text-white'}`}
                      title="Hiệu ứng Zoom"
                   >
                      <SlidersHorizontal size={12} className="mr-1.5" />
                      Zoom
                   </button>
                   <button 
                      onClick={() => toggleTool('subtitle')}
                      className={`flex items-center text-xs font-medium px-3 py-1.5 rounded-md border transition-all ${activeTool === 'subtitle' ? 'bg-[#0078d4] text-white border-[#0078d4]' : 'bg-[#252525] text-gray-400 border-[#333] hover:text-white'}`}
                      title="Phụ đề / Văn bản"
                   >
                      <Type size={12} className="mr-1.5" />
                      Phụ đề
                   </button>
                 </div>
               </div>

               {/* Zoom Tool Panel */}
               {activeTool === 'zoom' && (
                 <div className="bg-[#252525] border border-[#333] rounded-lg p-4 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="flex items-center space-x-2 mb-3 pb-2 border-b border-[#333]">
                      <ZoomIn size={16} className="text-[#0078d4]" />
                      <span className="text-sm font-semibold text-gray-200">Cấu hình Zoom Video</span>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-4">
                       <div>
                          <label className="block text-xs text-gray-400 mb-1.5">Tỷ lệ phóng đại (x{zoomLevel})</label>
                          <input 
                            type="range" 
                            min="1.1" 
                            max="5.0" 
                            step="0.1" 
                            value={zoomLevel} 
                            onChange={(e) => setZoomLevel(parseFloat(e.target.value))}
                            className="w-full h-1.5 bg-[#444] rounded-lg appearance-none cursor-pointer accent-[#0078d4]"
                          />
                       </div>
                       <div>
                          <label className="block text-xs text-gray-400 mb-1.5">Vị trí tập trung</label>
                          <select 
                             value={zoomPosition}
                             onChange={(e) => setZoomPosition(e.target.value)}
                             className="w-full bg-[#333] border border-[#444] text-gray-200 text-xs rounded px-2 py-1.5 focus:outline-none focus:border-[#0078d4]"
                          >
                             <option value="center">Giữa (Center)</option>
                             <option value="top-left">Trái - Trên</option>
                             <option value="top-right">Phải - Trên</option>
                             <option value="bottom-left">Trái - Dưới</option>
                             <option value="bottom-right">Phải - Dưới</option>
                          </select>
                       </div>
                    </div>

                    <button 
                      onClick={handleAddZoom}
                      className="w-full py-1.5 bg-[#333] hover:bg-[#444] text-xs font-medium text-blue-400 rounded transition-colors flex items-center justify-center"
                    >
                      <Plus size={12} className="mr-1.5" /> Thêm vào yêu cầu
                    </button>
                 </div>
               )}

               {/* Trim Tool Panel */}
               {activeTool === 'trim' && (
                  <div className="bg-[#252525] border border-[#333] rounded-lg p-4 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="flex items-center space-x-2 mb-3 pb-2 border-b border-[#333]">
                      <Scissors size={16} className="text-[#0078d4]" />
                      <span className="text-sm font-semibold text-gray-200">Cắt / Trim Video</span>
                    </div>

                    <div className="grid grid-cols-2 gap-4 mb-4">
                      <div>
                        <label className="block text-xs text-gray-400 mb-1.5">Thời gian bắt đầu</label>
                        <input 
                          type="text" 
                          placeholder="VD: 00:00:10" 
                          value={trimStart}
                          onChange={(e) => setTrimStart(e.target.value)}
                          className="w-full bg-[#333] border border-[#444] text-gray-200 text-xs rounded px-3 py-2 focus:outline-none focus:border-[#0078d4] placeholder-gray-600"
                        />
                      </div>
                      <div>
                        <label className="block text-xs text-gray-400 mb-1.5">Thời gian kết thúc</label>
                        <input 
                          type="text" 
                          placeholder="VD: 00:00:30" 
                          value={trimEnd}
                          onChange={(e) => setTrimEnd(e.target.value)}
                          className="w-full bg-[#333] border border-[#444] text-gray-200 text-xs rounded px-3 py-2 focus:outline-none focus:border-[#0078d4] placeholder-gray-600"
                        />
                      </div>
                    </div>

                    <button 
                      onClick={handleAddTrim}
                      disabled={!trimStart && !trimEnd}
                      className="w-full py-1.5 bg-[#333] hover:bg-[#444] disabled:opacity-50 disabled:cursor-not-allowed text-xs font-medium text-blue-400 rounded transition-colors flex items-center justify-center"
                    >
                      <Plus size={12} className="mr-1.5" /> Thêm yêu cầu cắt
                    </button>
                  </div>
               )}

               {/* Subtitle Tool Panel */}
               {activeTool === 'subtitle' && (
                 <div className="bg-[#252525] border border-[#333] rounded-lg p-4 animate-in fade-in slide-in-from-top-2 duration-200">
                   <div className="flex items-center space-x-2 mb-3 pb-2 border-b border-[#333]">
                     <Type size={16} className="text-[#0078d4]" />
                     <span className="text-sm font-semibold text-gray-200">Chèn Phụ Đề / Văn Bản</span>
                   </div>

                   <div className="flex space-x-2 mb-4">
                     <button
                       onClick={() => setSubMode('text')}
                       className={`flex-1 py-1.5 text-xs rounded border transition-colors ${subMode === 'text' ? 'bg-[#0078d4]/20 border-[#0078d4] text-[#0078d4]' : 'border-[#444] text-gray-400'}`}
                     >
                       Nhập văn bản
                     </button>
                     <button
                       onClick={() => setSubMode('file')}
                       className={`flex-1 py-1.5 text-xs rounded border transition-colors ${subMode === 'file' ? 'bg-[#0078d4]/20 border-[#0078d4] text-[#0078d4]' : 'border-[#444] text-gray-400'}`}
                     >
                       File Phụ đề (.srt)
                     </button>
                   </div>

                   {subMode === 'text' ? (
                     <div className="space-y-3">
                       <input 
                         type="text" 
                         placeholder="Nội dung văn bản..." 
                         value={subText}
                         onChange={(e) => setSubText(e.target.value)}
                         className="w-full bg-[#333] border border-[#444] text-gray-200 text-xs rounded px-3 py-2 focus:outline-none focus:border-[#0078d4] placeholder-gray-600"
                       />
                       <div className="flex space-x-3">
                         <input 
                           type="text" 
                           placeholder="Bắt đầu (giây)" 
                           value={subTime}
                           onChange={(e) => setSubTime(e.target.value)}
                           className="w-1/2 bg-[#333] border border-[#444] text-gray-200 text-xs rounded px-3 py-2 focus:outline-none focus:border-[#0078d4] placeholder-gray-600"
                         />
                         <input 
                           type="text" 
                           placeholder="Thời lượng (giây)" 
                           value={subDuration}
                           onChange={(e) => setSubDuration(e.target.value)}
                           className="w-1/2 bg-[#333] border border-[#444] text-gray-200 text-xs rounded px-3 py-2 focus:outline-none focus:border-[#0078d4] placeholder-gray-600"
                         />
                       </div>
                     </div>
                   ) : (
                     <div 
                       onClick={() => subFileInputRef.current?.click()}
                       className="border border-dashed border-[#444] hover:border-[#0078d4] rounded-lg p-4 cursor-pointer text-center bg-[#2a2a2a] transition-colors"
                     >
                       <input 
                         type="file" 
                         ref={subFileInputRef} 
                         onChange={handleSubFileChange} 
                         accept=".srt,.vtt,.ass" 
                         className="hidden" 
                       />
                       <FileText size={20} className="mx-auto mb-2 text-gray-400" />
                       <p className="text-xs text-gray-300">
                         {subFile ? subFile.name : "Chọn file .srt, .vtt"}
                       </p>
                     </div>
                   )}

                   <button 
                     onClick={handleAddSubtitle}
                     disabled={subMode === 'text' ? !subText : !subFile}
                     className="w-full mt-4 py-1.5 bg-[#333] hover:bg-[#444] disabled:opacity-50 disabled:cursor-not-allowed text-xs font-medium text-blue-400 rounded transition-colors flex items-center justify-center"
                   >
                     <Plus size={12} className="mr-1.5" /> Thêm phụ đề
                   </button>
                 </div>
               )}

             </div>

          </section>

          {/* Generate Button */}
          <div className="pt-2">
             {error && (
               <div className="mb-4 p-3 bg-red-900/20 border border-red-900/50 rounded-md flex items-start text-sm text-red-200">
                 <AlertCircle size={16} className="mt-0.5 mr-2 flex-shrink-0" />
                 {error}
               </div>
             )}

             <Button 
               onClick={handleGenerate} 
               disabled={isGenerating || !prompt || (inputMode === 'local' && localFiles.length === 0)}
               className="w-full h-11 text-base font-semibold shadow-[0_4px_14px_0_rgba(0,118,255,0.39)] hover:shadow-[0_6px_20px_rgba(0,118,255,0.23)] transition-shadow"
             >
               {isGenerating ? (
                 <span className="flex items-center">
                   <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></span>
                   Đang xử lý...
                 </span>
               ) : (
                 <span className="flex items-center">
                   <Wand2 size={18} className="mr-2" /> Tạo Script
                 </span>
               )}
             </Button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 lg:p-10 flex flex-col h-screen relative overflow-hidden bg-[#111]">

        {/* Subtle Background Glows */}
        <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-[#0078d4]/10 rounded-full blur-[120px] pointer-events-none" />
        <div className="absolute bottom-[-20%] left-[-10%] w-[500px] h-[500px] bg-purple-900/10 rounded-full blur-[100px] pointer-events-none" />

        <div className="flex-1 flex flex-col h-full z-10 gap-6 max-w-5xl mx-auto w-full">

          {/* Code Viewer */}
          <div className="flex-1 min-h-0 shadow-2xl rounded-lg">
            <CodeViewer code={code} isLoading={isGenerating} />
          </div>

          {/* Explanation Card */}
          {(explanation && !isGenerating) && (
            <div className="bg-[#1e1e1e] border border-[#333] rounded-lg p-5 shadow-xl animate-in fade-in slide-in-from-bottom-4 duration-500 max-h-[35%] overflow-y-auto custom-scrollbar">
               <div className="flex items-center mb-3">
                 <div className="p-1.5 bg-green-500/10 rounded-md mr-3">
                   <PlayCircle size={18} className="text-green-500" />
                 </div>
                 <h3 className="text-gray-200 font-semibold text-sm uppercase tracking-wide">
                   Hướng dẫn thực thi
                 </h3>
               </div>
               <div className="prose prose-invert prose-sm max-w-none text-gray-400 leading-relaxed whitespace-pre-line">
                 {explanation}
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { GoogleGenAI } from "@google/genai";
import { LibraryPreference } from "../types";

// Initialize Gemini Client
// We assume process.env.API_KEY is available as per instructions.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = "gemini-3-pro-preview"; // Using Pro for better coding logic

export const generatePythonScript = async (
  prompt: string,
  library: LibraryPreference,
  onStream: (chunkText: string) => void
): Promise<string> => {
  try {
    const systemInstruction = `
      You are an expert Python automation engineer specializing in video processing and media acquisition.
      Your goal is to generate robust, production-ready Python scripts to download and edit videos based on user requests.

      Primary Libraries & Capabilities:
      - yt-dlp: For downloading videos from YouTube, TikTok, Facebook, Twitter, and other social platforms.
      - MoviePy / FFmpeg / OpenCV: For editing, processing, and analyzing video content.

      Guidelines:
      1. Library Selection:
         - If the user asks to DOWNLOAD videos (from a URL or general request), ALWAYS use the 'yt-dlp' library for that part of the task.
         - If the user asks to EDIT videos, use the user's preferred library: ${library}.
         - If the user asks to DOWNLOAD AND EDIT, combine them: use 'yt-dlp' to download the file to a temporary or specific path, then use ${library} to process that downloaded file.

      2. **CRITICAL - MOVIEPY IMPORTS (Fix for 'No module named moviepy.editor')**:
         - **DO NOT USE**: \`from moviepy.editor import *\` or \`import moviepy.editor as mp\`. This module is deprecated/removed in newer versions.
         - **USE DIRECT IMPORTS**: Import specific classes directly from the main package.
           Example: \`from moviepy import VideoFileClip, TextClip, CompositeVideoClip, concatenate_videoclips, vfx, AudioFileClip\`
         - For effects in MoviePy v2+: Use the \`vfx\` module import or method chaining correctly.

      3. Script Structure:
         - Clean structure (imports -> functions -> main execution).
         - If downloading, include error handling (try/except) for network issues or invalid URLs.
         - Use descriptive variable names (e.g., 'input_video_path', 'output_final.mp4').

      4. Language & Comments:
         - **IMPORTANT**: Write all comments (#) in VIETNAMESE (Tiếng Việt).
         - The variable names and logic must remain in English (standard Python practice), but the explanation within the code must be Vietnamese.

      5. Output Format:
         - DO NOT wrap code in markdown (\`\`\`python). Return plain text code.
         - Add a comment block at the top named 'Yêu cầu cài đặt' listing pip packages.
           - Example for MoviePy: \`# pip install moviepy yt-dlp\`

      6. Special Video Effects Logic (Apply when requested):
         - **Trimming / Cutting**:
           - MoviePy: Use \`clip.subclipped(start_time, end_time)\`. ensure start/end are in seconds or (min, sec) format.
           - FFmpeg: Use \`ffmpeg.input(..., ss=start_time).output(..., to=end_time)\` for fast seeking.
         - **Speed Change**: 
           - MoviePy: Use \`clip.with_speed_scaled(factor)\` (v2) or \`clip.fx(vfx.speedx, factor)\`.
           - FFmpeg: Use \`setpts\` filter for video and \`atempo\` for audio.
         - **Subtitles / Text Overlay**:
           - **MoviePy (Text)**: Use \`TextClip(text="...", font_size=..., color='white', font='Arial')\`.
             Set duration: \`.with_duration(...)\`.
             Set position: \`.with_position(('center', 'bottom'))\`.
             **Crucial**: Combine using \`CompositeVideoClip([base_video, text_clip])\`.
           - **MoviePy (File)**: If user provides a .srt/.vtt file, mention that \`SubtitlesClip\` requires ImageMagick, or suggest using FFmpeg for hard burning.
           - **FFmpeg**: 
             - Text: Use \`drawtext\` filter.
             - File: Use \`subtitles='filename.srt'\` filter (best for hard subs).
         - **Audio Processing**:
           - **MoviePy**:
             - Adjust Volume: Use \`clip.with_volume_scaled(factor)\` (v2) or \`clip.volumex(factor)\`.
             - Remove Audio: Use \`clip.without_audio()\`.
             - Replace Audio: Load audio \`audio = AudioFileClip("file.mp3")\`. Set to video: \`clip.with_audio(audio)\`. Ensure durations match or loop (e.g. \`audio.subclipped(0, clip.duration)\`).
           - **FFmpeg**:
             - Adjust Volume: Use filter \`-filter:a "volume=1.5"\` (150%).
             - Remove Audio: Use flag \`-an\`.
             - Replace Audio: Input both files \`-i vid.mp4 -i aud.mp3\`. Map streams \`-map 0:v -map 1:a\`. Use \`-shortest\` if needed.
         - **Zoom (Magnification)**:
           - **Concept**: To zoom, you must crop a smaller area and resize it back to the original dimensions.
           - MoviePy: 
             \`new_w = clip.w / zoom_factor\`
             \`new_h = clip.h / zoom_factor\`
             \`clip.cropped(x_center=clip.w/2, y_center=clip.h/2, width=new_w, height=new_h).resized(width=clip.w)\`
             (Adjust x_center/y_center if the user requests zooming into a specific corner).
           - FFmpeg: Use \`scale\` and \`crop\` filters.

      7. Concatenation / Merging Logic (Apply when requested):
         - **MoviePy**: Use \`concatenate_videoclips([clip1, clip2, ...])\`. 
           - **Crucial**: If videos might have different sizes, use \`method='compose'\` to prevent errors.
         - **FFmpeg**: 
           - Preferred: Use the 'concat demuxer' method (create a temporary 'mylist.txt' file) if codecs are same.
           - Alternative: Use \`concat\` filter complex if re-encoding is needed or formats differ.

      8. Impossible Tasks:
         - If the requested library cannot perform a specific task, switch to the best alternative and explain why in the comments (in Vietnamese).
    `;

    const chat = ai.chats.create({
      model: MODEL_NAME,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.2, // Low temperature for precise code
        maxOutputTokens: 8192, // Allow long scripts
      },
    });

    const resultStream = await chat.sendMessageStream({
      message: `Write a Python script to: ${prompt}`,
    });

    let fullText = "";
    for await (const chunk of resultStream) {
      const text = chunk.text;
      if (text) {
        fullText += text;
        onStream(text);
      }
    }

    return fullText;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const explainScript = async (code: string): Promise<string> => {
   try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: `Giải thích đoạn mã Python tự động hóa video này một cách đơn giản cho người dùng bằng Tiếng Việt. Nếu mã chứa các hiệu ứng hoặc nối video, hãy giải thích ngắn gọn cách chúng hoạt động. Giữ ngắn gọn:\n\n${code}`,
    });
    return response.text || "Không thể tạo hướng dẫn.";
   } catch (error) {
     return "Không thể tạo hướng dẫn.";
   }
}

import React, { useState, useRef } from 'react';
import { generatePythonScript, explainScript } from './services/geminiService';
import { LibrarySelector } from './components/LibrarySelector';
import { CodeViewer } from './components/CodeViewer';
import { Button } from './components/Button';
import { LibraryPreference } from './types';
import { Wand2, PlayCircle, AlertCircle, FileVideo, Terminal, Sparkles, Upload, Link as LinkIcon, FolderOpen, X, Plus, ZoomIn, SlidersHorizontal, Scissors, Type, FileText, Volume2, VolumeX, Music } from 'lucide-react';

export default function App() {
  const [prompt, setPrompt] = useState('');
  const [library, setLibrary] = useState<LibraryPreference>(LibraryPreference.MOVIEPY);
  const [code, setCode] = useState('');
  const [explanation, setExplanation] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // New states for input mode
  const [inputMode, setInputMode] = useState<'url' | 'local'>('url');
  // Changed to array to support multiple files
  const [localFiles, setLocalFiles] = useState<File[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Active Tool State (Only one tool open at a time)
  const [activeTool, setActiveTool] = useState<'zoom' | 'trim' | 'subtitle' | 'audio' | null>(null);

  // Zoom Tool State
  const [zoomLevel, setZoomLevel] = useState(1.5);
  const [zoomPosition, setZoomPosition] = useState('center');

  // Trim Tool State
  const [trimStart, setTrimStart] = useState('');
  const [trimEnd, setTrimEnd] = useState('');

  // Subtitle Tool State
  const [subMode, setSubMode] = useState<'text' | 'file'>('text');
  const [subText, setSubText] = useState('');
  const [subFile, setSubFile] = useState<File | null>(null);
  const [subTime, setSubTime] = useState('');
  const [subDuration, setSubDuration] = useState('');
  const subFileInputRef = useRef<HTMLInputElement>(null);

  // Audio Tool State
  const [audioMode, setAudioMode] = useState<'volume' | 'mute' | 'replace'>('volume');
  const [volumeLevel, setVolumeLevel] = useState(1.0); // 1.0 = 100%
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const audioFileInputRef = useRef<HTMLInputElement>(null);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setIsGenerating(true);
    setError(null);
    setCode('');
    setExplanation('');

    try {
      // Construct the full prompt based on mode
      let finalPrompt = prompt;

      if (inputMode === 'local') {
        const filenames = localFiles.map(f => `"${f.name}"`).join(", ");
        finalPrompt = `I have the following local video files in the same directory as the script: [${filenames}]. ${prompt}`;
      } else {
        finalPrompt = `Source is from URL/Internet. ${prompt}`;
      }

      const generatedCode = await generatePythonScript(finalPrompt, library, (chunk) => {
        setCode(prev => prev + chunk);
      });
      explainScript(generatedCode).then(setExplanation);
    } catch (err: any) {
      setError(err.message || "Lỗi tạo script. Vui lòng thử lại.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleQuickPrompt = (text: string) => {
    setPrompt(text);
  };

  const toggleTool = (tool: 'zoom' | 'trim' | 'subtitle' | 'audio') => {
    setActiveTool(activeTool === tool ? null : tool);
  };

  const handleAddZoom = () => {
    const positionText = zoomPosition === 'center' ? 'tâm (center)' : 
                         zoomPosition === 'top-left' ? 'góc trên bên trái (top-left)' :
                         zoomPosition === 'top-right' ? 'góc trên bên phải (top-right)' :
                         zoomPosition === 'bottom-left' ? 'góc dưới bên trái (bottom-left)' :
                         'góc dưới bên phải (bottom-right)';

    const zoomText = ` Zoom video phóng đại ${zoomLevel}x tập trung vào vị trí ${positionText}.`;
    setPrompt(prev => prev + zoomText);
    setActiveTool(null);
  };

  const handleAddTrim = () => {
    if (!trimStart && !trimEnd) return;
    let trimText = " Cắt video";
    if (trimStart) trimText += ` bắt đầu từ ${trimStart}`;
    if (trimEnd) trimText += ` và kết thúc tại ${trimEnd}`;
    trimText += ".";

    setPrompt(prev => prev + trimText);
    setActiveTool(null);
    setTrimStart('');
    setTrimEnd('');
  };

  const handleAddSubtitle = () => {
    let subPrompt = "";
    if (subMode === 'text') {
      if (!subText) return;
      subPrompt = ` Chèn văn bản "${subText}" vào video`;
      if (subTime) subPrompt += ` bắt đầu từ giây thứ ${subTime}`;
      if (subDuration) subPrompt += ` kéo dài trong ${subDuration} giây`;
      subPrompt += ".";
    } else {
      if (!subFile) return;
      subPrompt = ` Chèn phụ đề cứng (hardcode subtitles) từ file "${subFile.name}" vào video.`;
    }

    setPrompt(prev => prev + subPrompt);
    setActiveTool(null);
    setSubText('');
    setSubTime('');
    setSubDuration('');
    setSubFile(null);
  };

  const handleAddAudio = () => {
    let audioPrompt = "";
    if (audioMode === 'volume') {
      audioPrompt = ` Chỉnh âm lượng video thành ${Math.round(volumeLevel * 100)}%.`;
    } else if (audioMode === 'mute') {
      audioPrompt = ` Xóa bỏ âm thanh gốc (Mute/Remove Audio).`;
    } else if (audioMode === 'replace') {
      if (!audioFile) return;
      audioPrompt = ` Thay thế âm thanh gốc bằng file âm thanh "${audioFile.name}".`;
    }

    setPrompt(prev => prev + audioPrompt);
    setActiveTool(null);
    setAudioFile(null);
    setVolumeLevel(1.0);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFiles = Array.from(e.target.files);
      setLocalFiles(prev => {
        const uniqueNewFiles = newFiles.filter(nf => !prev.some(pf => pf.name === nf.name));
        return [...prev, ...uniqueNewFiles];
      });
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setSubFile(e.target.files[0]);
    }
    if (subFileInputRef.current) subFileInputRef.current.value = '';
  };

  const handleAudioFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setAudioFile(e.target.files[0]);
    }
    if (audioFileInputRef.current) audioFileInputRef.current.value = '';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const droppedFiles = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('video/'));
      if (droppedFiles.length === 0) {
         setError("Vui lòng chỉ thả file video.");
         setTimeout(() => setError(null), 3000);
         return;
      }
      setLocalFiles(prev => {
        const uniqueNewFiles = droppedFiles.filter(nf => !prev.some(pf => pf.name === nf.name));
        return [...prev, ...uniqueNewFiles];
      });
    }
  };

  const removeFile = (index: number) => {
    setLocalFiles(prev => prev.filter((_, i) => i !== index));
  };

  // Modern "Chip" component for quick prompts
  const QuickChip = ({ label, onClick }: { label: string, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="text-xs font-medium bg-[#333] hover:bg-[#444] text-gray-200 px-3 py-1.5 rounded-full border border-[#444] transition-colors flex items-center space-x-1"
    >
      <Sparkles size={10} className="text-[#0078d4]" />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="min-h-screen bg-[#111] text-gray-100 flex flex-col md:flex-row overflow-hidden font-sans selection:bg-[#0078d4] selection:text-white">

      {/* Sidebar - Acrylic Style */}
      <div className="w-full md:w-[420px] flex flex-col bg-[#1c1c1c]/95 backdrop-blur-md border-r border-[#333] h-screen overflow-y-auto z-20 shadow-2xl">
        <div className="p-6 border-b border-[#333] sticky top-0 bg-[#1c1c1c]/95 backdrop-blur-xl z-30">
          <div className="flex items-center space-x-3 mb-1">
             <div className="w-9 h-9 bg-gradient-to-br from-[#0078d4] to-[#005a9e] rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
                <FileVideo size={20} className="text-white" />
             </div>
             <div>
                <h1 className="text-lg font-bold text-white tracking-tight">
                  AutoEditPy
                </h1>
                <div className="flex items-center space-x-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
                  <p className="text-[11px] text-gray-400 font-medium">v1.2 • Pro</p>
                </div>
             </div>
          </div>
        </div>

        <div className="p-6 flex-1 flex flex-col space-y-7">

          {/* Section: Library */}
          <section>
            <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center pl-1">
              Thư viện xử lý
            </h2>
            <LibrarySelector selected={library} onSelect={setLibrary} />
          </section>

          {/* Section: Input Source Mode */}
          <section>
             <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center pl-1">
              Nguồn Video
            </h2>
            <div className="bg-[#252525] p-1 rounded-lg flex border border-[#333] mb-4">
              <button 
                onClick={() => setInputMode('url')}
                className={`flex-1 flex items-center justify-center py-2 text-sm font-medium rounded-md transition-all ${inputMode === 'url' ? 'bg-[#333] text-white shadow-sm' : 'text-gray-400 hover:text-gray-200'}`}
              >
                <LinkIcon size={14} className="mr-2" /> URL Online
              </button>
              <button 
                onClick={() => setInputMode('local')}
                className={`flex-1 flex items-center justify-center py-2 text-sm font-medium rounded-md transition-all ${inputMode === 'local' ? 'bg-[#333] text-white shadow-sm' : 'text-gray-400 hover:text-gray-200'}`}
              >
                <Upload size={14} className="mr-2" /> File Cục bộ
              </button>
            </div>

            {/* Local File Uploader Area */}
            {inputMode === 'local' && (
              <div className="space-y-3">
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  onDragOver={handleDragOver}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDrop}
                  className={`
                    group relative border-2 border-dashed rounded-xl p-6 cursor-pointer transition-all flex flex-col items-center justify-center text-center
                    ${isDragging ? 'border-[#0078d4] bg-[#0078d4]/10' : 'border-[#444] hover:border-[#0078d4] bg-[#252525]/50 hover:bg-[#252525]'}
                  `}
                >
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    onChange={handleFileChange} 
                    accept="video/*"
                    multiple // Allow multiple files
                  />

                  <div className={`w-12 h-12 rounded-full flex items-center justify-center mb-3 transition-colors ${isDragging ? 'bg-[#0078d4] text-white' : 'bg-[#333] group-hover:bg-[#444] text-gray-400 group-hover:text-[#0078d4]'}`}>
                    {isDragging ? <Plus size={24} /> : <FolderOpen size={24} />}
                  </div>
                  <p className="text-sm font-medium text-gray-300">Nhấn chọn hoặc kéo thả video</p>
                  <p className="text-xs text-gray-500 mt-1">Hỗ trợ chọn nhiều file để nối/ghép</p>
                </div>

                {/* File List */}
                {localFiles.length > 0 && (
                  <div className="max-h-[150px] overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                    {localFiles.map((file, index) => (
                      <div key={`${file.name}-${index}`} className="flex items-center space-x-3 w-full bg-[#2a2a2a] p-2 rounded-lg border border-[#333] group hover:border-[#444] transition-colors">
                        <div className="w-8 h-8 bg-[#0078d4]/20 rounded-md flex items-center justify-center flex-shrink-0 text-[#0078d4]">
                          <FileVideo size={16} />
                        </div>
                        <div className="flex-1 min-w-0 text-left">
                          <p className="text-sm font-medium text-gray-200 truncate">{file.name}</p>
                          <p className="text-[10px] text-gray-500">{(file.size / (1024 * 1024)).toFixed(2)} MB</p>
                        </div>
                        <button 
                          onClick={(e) => { e.stopPropagation(); removeFile(index); }} 
                          className="p-1.5 hover:bg-red-900/30 text-gray-500 hover:text-red-400 rounded-md transition-colors"
                          title="Xóa file"
                        >
                          <X size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </section>

          {/* Section: Prompt */}
          <section className="flex-1 flex flex-col">
            <h2 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center pl-1">
              Yêu cầu xử lý
            </h2>

            <div className="relative group">
              <div className="absolute -inset-0.5 bg-gradient-to-r from-[#0078d4] to-[#00bcf2] rounded-xl opacity-20 group-hover:opacity-40 transition duration-500 blur"></div>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder={inputMode === 'local' 
                  ? "Ví dụ: Nối tất cả video trên lại thành 1 file, sau đó thêm nhạc nền..." 
                  : "Ví dụ: Tải video từ YouTube URL, cắt lấy đoạn 00:30 đến 01:00..."
                }
                className="relative w-full min-h-[120px] bg-[#252525] border border-[#333] text-gray-100 rounded-lg p-4 text-sm focus:ring-2 focus:ring-[#0078d4] focus:border-transparent outline-none resize-none placeholder-gray-500 transition-all shadow-inner"
              />
            </div>

             {/* Tools & Effects Bar */}
             <div className="mt-4 flex flex-col space-y-3">
               <div className="flex items-center justify-between">
