import { LibraryPreference } from './types';
import { Wand2, PlayCircle, AlertCircle, FileVideo, Terminal, Sparkles, Upload, Link as LinkIcon, FolderOpen, X, Plus, ZoomIn, SlidersHorizontal, Scissors, Type, FileText, Volume2, VolumeX, Music, ArrowRightLeft, CheckCircle, FlipHorizontal, FlipVertical, Image as ImageIcon, Mic, Square, Download, Settings, Moon, Sun, Palette } from 'lucide-react';

// Color Palette Options
const THEME_COLORS = [
  { name: 'Blue', value: '#0078d4' },
  { name: 'Purple', value: '#8b5cf6' },
  { name: 'Green', value: '#10b981' },
  { name: 'Orange', value: '#f97316' },
