                 </div>
               )}

             </div>

          </section>

          {/* Generate Button */}
          <div className="pt-2">
             {error && (
               <div className="mb-4 p-3 bg-red-900/20 border border-red-900/50 rounded-md flex items-start text-sm text-red-200"><AlertCircle size={16} className="mt-0.5 mr-2 flex-shrink-0" />{error}</div>
